package fraymus.workspace;
import org.json.*;
import java.nio.*;
import java.nio.file.*;
import java.nio.channels.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;

/** Authored state, provisional native experiments and accepted world revisions remain distinct. */
final class SmallStore161 implements AutoCloseable {
 final Path root,nativeDir;final WorkspaceStore artifacts;JSONObject state;boolean closed;
 final ExecutorService worker=Executors.newSingleThreadExecutor(r->{var t=new Thread(r,"small-body161");t.setDaemon(true);return t;});
 SmallStore161(Path project,WorkspaceStore artifacts)throws Exception{root=project.resolve("small-body161/state.json");nativeDir=project.resolve("native");this.artifacts=artifacts;state=Files.exists(root)?load():new JSONObject().put("worlds",new JSONArray()).put("jobs",new JSONArray());for(Object raw:state.getJSONArray("jobs")){var j=(JSONObject)raw;if(j.getString("status").equals("running"))j.put("status","interrupted").put("reason","Process ended; resume repeats the provisional attempt from the same accepted state");}save();}
 JSONObject load()throws Exception{ReplayEvidence157.unlinkedRealPath(root);if(Files.size(root)>48_000_000)throw new IllegalStateException("Small-world evidence budget exceeded");var e=new JSONObject(Files.readString(root));if(!WorldFrames.hash(e.getJSONObject("payload")).equals(e.getString("sha256")))throw new IllegalStateException("Small-world checksum changed");return e.getJSONObject("payload");}
 void save()throws Exception{try{Files.createDirectories(root.getParent());var bytes=new JSONObject().put("payload",state).put("sha256",WorldFrames.hash(state)).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);if(bytes.length>48_000_000)throw new IllegalStateException("Small-world evidence budget exceeded");var tmp=root.resolveSibling("state.pending");try(var c=FileChannel.open(tmp,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING,StandardOpenOption.WRITE)){var b=ByteBuffer.wrap(bytes);while(b.hasRemaining())c.write(b);c.force(true);}Files.move(tmp,root,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(Exception failure){try{state=Files.exists(root)?load():new JSONObject().put("worlds",new JSONArray()).put("jobs",new JSONArray());}catch(Exception rollback){closed=true;failure.addSuppressed(rollback);}throw failure;}}
 JSONObject find(String kind,String id){UUID.fromString(id);for(Object raw:state.getJSONArray(kind))if(((JSONObject)raw).getString("id").equals(id))return (JSONObject)raw;throw new IllegalArgumentException("Unknown small-world "+kind);}
 synchronized JSONObject read(String id){return WorldFrames.copy(find("jobs",id));}
 synchronized JSONObject world(String id){return WorldFrames.copy(find("worlds",id));}
 synchronized JSONObject list(){var worlds=new JSONArray();for(Object raw:state.getJSONArray("worlds")){var w=(JSONObject)raw;worlds.put(new JSONObject().put("id",w.getString("id")).put("title",w.getString("title")).put("revision",w.getInt("revision")).put("hash",w.getString("hash")).put("pending",w.optString("pending","")));}var jobs=new JSONArray();for(Object raw:state.getJSONArray("jobs")){var j=(JSONObject)raw;var row=new JSONObject();for(String k:List.of("id","worldId","status","generation","resumes","reason"))if(j.has(k))row.put(k,j.get(k));jobs.put(row);}return new JSONObject().put("worlds",worlds).put("jobs",jobs);}
 synchronized JSONObject create(JSONObject imported)throws Exception{if(closed||state.getJSONArray("worlds").length()>=8)throw new IllegalStateException("Small-world capacity reached");var scene=SmallBody161.authored(imported);var w=new JSONObject().put("id",UUID.randomUUID().toString()).put("title",scene.getString("title")).put("authored",scene).put("head",WorldFrames.copy(scene)).put("hash",WorldFrames.hash(scene)).put("revision",0).put("history",new JSONArray());state.getJSONArray("worlds").put(w);save();return WorldFrames.copy(w);}
 static void expected(JSONObject w,JSONObject input){if(input.getDouble("expectedRevision")!=w.getInt("revision")||!input.getString("expectedHash").equals(w.getString("hash")))throw new IllegalStateException("Observed small-world revision changed");}
 JSONObject preview(JSONObject in)throws Exception{verifyWorld(in.getString("worldId"));synchronized(this){SpatialScene.keys(in,"worldId","expectedRevision","expectedHash","action");var w=find("worlds",in.getString("worldId"));expected(w,in);if(w.has("pending"))throw new IllegalStateException("Finish or cancel the pending small-world experiment");return SmallBody161.plan(w.getJSONObject("head"),in.getJSONObject("action"));}}
 JSONObject start(JSONObject in)throws Exception{var plan=preview(in);synchronized(this){if(closed||state.getJSONArray("jobs").length()>=12)throw new IllegalStateException("Small-task capacity reached");idle();var w=find("worlds",in.getString("worldId"));expected(w,in);if(w.has("pending"))throw new IllegalStateException("Pending owner changed");var j=new JSONObject().put("id",UUID.randomUUID().toString()).put("worldId",w.getString("id")).put("before",WorldFrames.copy(w.getJSONObject("head"))).put("expectedHash",w.getString("hash")).put("expectedRevision",w.getInt("revision")).put("plan",plan).put("status","running").put("generation",1).put("resumes",0).put("engine",SmallBody161.identity()).put("attempts",new JSONArray()).put("createdAt",Instant.now());state.getJSONArray("jobs").put(j);w.put("pending",j.getString("id"));save();schedule(j);return WorldFrames.copy(j);}}
 void idle(){for(Object raw:state.getJSONArray("jobs"))if(((JSONObject)raw).getString("status").equals("running"))throw new IllegalStateException("One native small-body owner at a time");}
 synchronized JSONObject control(String id,String command)throws Exception{if(!Set.of("resume","stop","cancel").contains(command))throw new IllegalArgumentException("Unknown small-body command");var j=find("jobs",id);if(command.equals("resume")){idle();if(!Set.of("interrupted","failed").contains(j.getString("status"))||j.getInt("resumes")>=3)throw new IllegalStateException("Only interrupted/failed jobs resume, at most three times");engine(j);j.put("generation",j.getInt("generation")+1).put("resumes",j.getInt("resumes")+1).put("status","running");j.remove("reason");save();schedule(j);}else{if(!Set.of("running","interrupted","failed","awaiting-report").contains(j.getString("status")))throw new IllegalStateException("Finished small-body history is immutable");j.put("generation",j.getInt("generation")+1).put("status",command.equals("cancel")?"cancelled":"interrupted");if(command.equals("cancel"))find("worlds",j.getString("worldId")).remove("pending");save();}return WorldFrames.copy(j);}
 static void engine(JSONObject j){if(!j.getString("engine").equals(SmallBody161.identity()))throw new IllegalStateException("Small-domain evaluator changed; retain original evidence");}
 void schedule(JSONObject job){var frozen=WorldFrames.copy(job);worker.submit(()->{String id=frozen.getString("id");int generation=frozen.getInt("generation");long start=System.nanoTime();Runnable check=()->{synchronized(this){var j=find("jobs",id);if(closed||Thread.currentThread().isInterrupted()||!j.getString("status").equals("running")||j.getInt("generation")!=generation||System.nanoTime()-start>120_000_000_000L)throw new IllegalStateException("Small-body attempt interrupted or timed out");}};try{var run=SmallBody161.execute(frozen.getJSONObject("before"),frozen.getJSONObject("plan"),nativeDir,check);synchronized(this){check.run();var j=find("jobs",id);j.put("run",run).put("elapsedMs",(System.nanoTime()-start)/1e6);j.getJSONArray("attempts").put(new JSONObject().put("generation",generation).put("runHash",WorldFrames.hash(run)).put("status",run.getString("status")));var a=artifacts.writeOnce("small161:"+id,SmallReport161.build(j));j.put("report",Creation.reference(a)).put("status","awaiting-report");save();}}catch(Exception e){synchronized(this){var j=find("jobs",id);if(j.getInt("generation")==generation&&j.getString("status").equals("running"))try{j.put("status","failed").put("reason",e.getMessage());save();}catch(Exception ignored){/* Restart rechecks checksummed originals. */}}}});}
 JSONObject verified(String id)throws Exception{var j=read(id);engine(j);if(!Set.of("awaiting-report","completed","rejected").contains(j.getString("status")))throw new IllegalStateException("Native attempt is not complete");long begin=System.nanoTime();var replay=SmallBody161.execute(j.getJSONObject("before"),j.getJSONObject("plan"),nativeDir,()->{if(System.nanoTime()-begin>120_000_000_000L)throw new IllegalStateException("Verification deadline");});if(!replay.similar(j.getJSONObject("run")))throw new IllegalStateException("Original native trace differs from fresh replay");var a=artifacts.read(j.getJSONObject("report").getString("id"));if(a.getInt("version")!=1||!Creation.reference(a).similar(j.getJSONObject("report"))||!a.getJSONObject("contents").similar(SmallReport161.build(j).getJSONObject("files")))throw new IllegalStateException("Original small-body report changed");if(!read(id).similar(j))throw new IllegalStateException("Small-body job changed during verification");return j;}
 JSONObject prepare(String id)throws Exception{var j=verified(id);return new JSONObject().put("id",id).put("report",j.getJSONObject("report")).put("samples",j.getJSONObject("run").getJSONArray("samples").length());}
 JSONObject acknowledge(JSONObject input)throws Exception{SpatialScene.keys(input,"id","observed");var j=verified(input.getString("id"));var audit=SmallReport161.audit(j,input.getJSONObject("observed"));synchronized(this){if(!read(j.getString("id")).similar(j))throw new IllegalStateException("Stale small-world acknowledgement");if(Set.of("completed","rejected").contains(j.getString("status"))){if(!audit.similar(j.getJSONObject("audit")))throw new IllegalStateException("Rendered proof changed");return j;}var w=find("worlds",j.getString("worldId"));expected(w,j);if(!w.optString("pending").equals(j.getString("id")))throw new IllegalStateException("Small-world owner changed");var saved=find("jobs",j.getString("id"));saved.put("audit",audit);if(j.getJSONObject("run").getJSONObject("verification").getBoolean("passed")){var next=SmallBody161.after(j.getJSONObject("before"),j.getJSONObject("run"));w.put("head",next).put("hash",WorldFrames.hash(next)).put("revision",w.getInt("revision")+1);w.getJSONArray("history").put(new JSONObject().put("jobId",j.getString("id")).put("beforeHash",j.getString("expectedHash")).put("afterHash",w.getString("hash")));saved.put("status","completed").put("committedRevision",w.getInt("revision"));}else saved.put("status","rejected");w.remove("pending");save();return WorldFrames.copy(saved);}}
 JSONObject verify(String id)throws Exception{var j=verified(id);if(!Set.of("completed","rejected").contains(j.getString("status")))throw new IllegalStateException("Actual report acknowledgement required");SmallReport161.audit(j,j.getJSONObject("audit").getJSONObject("observed"));var w=verifyWorld(j.getString("worldId"));return new JSONObject().put("passed",true).put("worldRevision",w.getInt("revision")).put("nativePassed",j.getJSONObject("run").getJSONObject("verification").getBoolean("passed"));}
 JSONObject verifyWorld(String id)throws Exception{var w=world(id);var head=SmallBody161.authored(w.getJSONObject("authored"));if(!head.similar(w.getJSONObject("authored")))throw new IllegalStateException("Authored starting state changed");int rev=0;for(Object raw:w.getJSONArray("history")){var e=(JSONObject)raw;var prior=verified(e.getString("jobId"));SmallReport161.audit(prior,prior.getJSONObject("audit").getJSONObject("observed"));if(!prior.getString("worldId").equals(id)||!prior.getString("status").equals("completed")||prior.getInt("expectedRevision")!=rev||!prior.getJSONObject("before").similar(head)||!WorldFrames.hash(head).equals(e.getString("beforeHash"))||!prior.getString("expectedHash").equals(e.getString("beforeHash")))throw new IllegalStateException("Small-world ancestry changed");head=SmallBody161.after(head,prior.getJSONObject("run"));if(!WorldFrames.hash(head).equals(e.getString("afterHash")))throw new IllegalStateException("Small-world outcome changed");rev++;if(prior.getInt("committedRevision")!=rev)throw new IllegalStateException("Small-world committed revision changed");}if(w.getInt("revision")!=rev||!head.similar(w.getJSONObject("head"))||!WorldFrames.hash(head).equals(w.getString("hash"))||!world(id).similar(w))throw new IllegalStateException("Small-world accepted state changed");return w;}
 @Override public synchronized void close(){closed=true;worker.shutdownNow();}
}
